import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

swish_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void swish_forward_kernel(const float* x, float* out, int size) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        const float val = x[idx];
        const float sigmoid = 1.0f / (1.0f + expf(-val));
        out[idx] = val * sigmoid;
    }
}

torch::Tensor swish_forward_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    swish_forward_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

swish_cpp_source = "torch::Tensor swish_forward_cuda(torch::Tensor x);"

swish_module = load_inline(
    name='swish_activation',
    cpp_sources=swish_cpp_source,
    cuda_sources=swish_kernel_source,
    functions=['swish_forward_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.swish_forward = swish_module.swish_forward_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.swish_forward(x)
